/* ============================================
   ClipCast — Global Styles
   ============================================ */

:root {
  --primary: #1868DB;
  --primary-dark: #1457b8;
  --accent: #FF613D;
  --accent-light: #ff7a5c;
  --text: #292A2E;
  --text-secondary: #5a5c63;
  --text-muted: #8a8d96;
  --bg: #ffffff;
  --bg-warm: #f8f9fc;
  --bg-alt: #f0f2f8;
  --border: #e2e5ee;
  --border-light: #eef0f5;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow: 0 4px 20px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 40px rgba(0,0,0,0.12);
  --radius-sm: 8px;
  --radius: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font);
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: var(--transition);
}

a:hover {
  color: var(--primary-dark);
}

img {
  max-width: 100%;
  display: block;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.container-narrow {
  max-width: 960px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ============================================
   Typography
   ============================================ */

h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); }

.section-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--primary);
  margin-bottom: 12px;
}

.section-label.new {
  background: var(--accent);
  color: #fff;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 0.7rem;
}

.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 48px;
}

.section-header h2 {
  margin-bottom: 16px;
}

.section-header p {
  font-size: 1.125rem;
  color: var(--text-secondary);
}

/* ============================================
   Buttons
   ============================================ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius);
  border: none;
  cursor: pointer;
  transition: var(--transition);
  text-decoration: none;
  white-space: nowrap;
}

.btn-primary {
  background: var(--primary);
  color: #fff;
}

.btn-primary:hover {
  background: var(--primary-dark);
  color: #fff;
  transform: translateY(-1px);
  box-shadow: var(--shadow);
}

.btn-accent {
  background: var(--accent);
  color: #fff;
}

.btn-accent:hover {
  background: #e55735;
  color: #fff;
  transform: translateY(-1px);
  box-shadow: var(--shadow);
}

.btn-outline {
  background: transparent;
  color: var(--text);
  border: 1.5px solid var(--border);
}

.btn-outline:hover {
  border-color: var(--text-muted);
  background: var(--bg-warm);
}

.btn-ghost {
  background: transparent;
  color: var(--primary);
}

.btn-ghost:hover {
  background: rgba(24, 104, 219, 0.08);
}

.btn-white {
  background: #fff;
  color: var(--primary);
}

.btn-white:hover {
  background: var(--bg-warm);
}

.btn-lg {
  padding: 14px 32px;
  font-size: 1rem;
}

.btn-sm {
  padding: 8px 16px;
  font-size: 0.875rem;
}

/* ============================================
   Navigation
   ============================================ */

.navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-light);
}

.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--text);
  display: flex;
  align-items: center;
  gap: 8px;
}

.logo-icon {
  width: 32px;
  height: 32px;
  background: linear-gradient(135deg, var(--primary), #4a90e2);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 0.875rem;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
  list-style: none;
}

.nav-links a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.nav-links a:hover {
  color: var(--text);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 4px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
}

.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text);
  border-radius: 2px;
  transition: var(--transition);
}

/* ============================================
   Hero
   ============================================ */

.hero {
  padding: 80px 0 64px;
  position: relative;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, #f0f5ff 0%, #fff 60%);
  z-index: -1;
}

.hero .container {
  text-align: center;
}

.hero h1 {
  max-width: 800px;
  margin: 0 auto 20px;
}

.hero p {
  font-size: 1.25rem;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 32px;
}

.hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.hero-visual {
  margin-top: 56px;
  position: relative;
}

.hero-visual-placeholder {
  width: 100%;
  max-width: 900px;
  height: 420px;
  margin: 0 auto;
  background: linear-gradient(135deg, #e8eeff, #f0e8ff);
  border-radius: var(--radius-xl);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-lg);
  position: relative;
  overflow: hidden;
}

.hero-visual-placeholder::before {
  content: '';
  position: absolute;
  width: 200px;
  height: 200px;
  background: radial-gradient(circle, rgba(24,104,219,0.15), transparent 70%);
  top: -40px;
  right: -40px;
}

.hero-visual-placeholder::after {
  content: '';
  position: absolute;
  width: 160px;
  height: 160px;
  background: radial-gradient(circle, rgba(255,97,61,0.12), transparent 70%);
  bottom: -30px;
  left: -30px;
}

/* ============================================
   Logo Bar
   ============================================ */

.logo-bar {
  padding: 40px 0;
  border-bottom: 1px solid var(--border-light);
}

.logo-bar p {
  text-align: center;
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 24px;
}

.logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
}

.logo-item {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--text-muted);
  opacity: 0.7;
  letter-spacing: -0.01em;
}

/* ============================================
   Feature Highlight
   ============================================ */

.feature-highlight {
  padding: 80px 0;
}

.feature-highlight .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.feature-highlight.reverse .container {
  direction: rtl;
}

.feature-highlight.reverse .feature-content {
  direction: ltr;
}

.feature-content h2 {
  margin-bottom: 16px;
}

.feature-content p {
  font-size: 1.0625rem;
  color: var(--text-secondary);
  margin-bottom: 24px;
}

.feature-visual {
  background: linear-gradient(135deg, #f0f5ff, #faf0ff);
  border-radius: var(--radius-lg);
  height: 360px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

/* ============================================
   Cards & Grids
   ============================================ */

.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
}

.card {
  background: var(--bg);
  border: 1px solid var(--border-light);
  border-radius: var(--radius);
  padding: 28px;
  transition: var(--transition);
}

.card:hover {
  box-shadow: var(--shadow);
  transform: translateY(-2px);
}

.card-icon {
  width: 48px;
  height: 48px;
  background: linear-gradient(135deg, var(--primary), #4a90e2);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 1.25rem;
  margin-bottom: 16px;
}

.card h3 {
  margin-bottom: 8px;
  font-size: 1.125rem;
}

.card p {
  font-size: 0.9375rem;
  color: var(--text-secondary);
}

/* ============================================
   Use Cases
   ============================================ */

.use-cases {
  padding: 80px 0;
  background: var(--bg-warm);
}

.use-case-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.use-case-card {
  background: var(--bg);
  border-radius: var(--radius);
  padding: 32px 24px;
  text-align: center;
  transition: var(--transition);
}

.use-case-card:hover {
  box-shadow: var(--shadow);
  transform: translateY(-2px);
}

.use-case-card .icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--primary), #4a90e2);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 1.5rem;
  margin: 0 auto 16px;
}

.use-case-card h3 {
  margin-bottom: 8px;
  font-size: 1.125rem;
}

.use-case-card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* ============================================
   Features Grid Section
   ============================================ */

.features-grid-section {
  padding: 80px 0;
}

.features-grid-section .card-grid {
  grid-template-columns: repeat(4, 1fr);
}

/* ============================================
   Testimonials
   ============================================ */

.testimonials {
  padding: 80px 0;
  background: var(--bg-warm);
}

.testimonial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.testimonial-card {
  background: var(--bg);
  border-radius: var(--radius);
  padding: 28px;
  transition: var(--transition);
}

.testimonial-card:hover {
  box-shadow: var(--shadow);
}

.testimonial-card p {
  font-size: 1rem;
  line-height: 1.7;
  margin-bottom: 20px;
  color: var(--text);
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-author .avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-weight: 700;
  font-size: 0.875rem;
}

.testimonial-author .name {
  font-weight: 600;
  font-size: 0.9375rem;
}

.testimonial-author .role {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* ============================================
   CTA Banner
   ============================================ */

.cta-banner {
  padding: 80px 0;
  position: relative;
  overflow: hidden;
}

.cta-banner.gradient {
  background: linear-gradient(135deg, var(--primary), #3a5bc7);
  color: #fff;
}

.cta-banner.gradient h2,
.cta-banner.gradient p {
  color: #fff;
}

.cta-banner .container {
  text-align: center;
  position: relative;
  z-index: 1;
}

.cta-banner h2 {
  margin-bottom: 16px;
}

.cta-banner p {
  font-size: 1.125rem;
  margin-bottom: 28px;
  opacity: 0.9;
}

/* ============================================
   Footer
   ============================================ */

.footer {
  background: var(--text);
  color: #a0a3ad;
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(5, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer-brand .logo {
  color: #fff;
  margin-bottom: 12px;
}

.footer-brand p {
  font-size: 0.875rem;
  line-height: 1.6;
  max-width: 280px;
}

.footer-col h4 {
  color: #fff;
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 16px;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 10px;
}

.footer-col a {
  color: #a0a3ad;
  font-size: 0.875rem;
}

.footer-col a:hover {
  color: #fff;
}

.footer-bottom {
  border-top: 1px solid #3a3c44;
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8125rem;
}

/* ============================================
   Pricing Page
   ============================================ */

.pricing-hero {
  padding: 60px 0 40px;
  text-align: center;
}

.pricing-hero h1 {
  margin-bottom: 12px;
}

.pricing-hero p {
  color: var(--text-secondary);
  font-size: 1.125rem;
}

.billing-toggle {
  display: inline-flex;
  align-items: center;
  gap: 16px;
  background: var(--bg-warm);
  padding: 6px;
  border-radius: 40px;
  margin: 32px 0;
}

.billing-toggle button {
  padding: 8px 20px;
  border-radius: 30px;
  border: none;
  background: transparent;
  font-size: 0.9375rem;
  font-weight: 600;
  cursor: pointer;
  color: var(--text-secondary);
  transition: var(--transition);
}

.billing-toggle button.active {
  background: var(--primary);
  color: #fff;
}

.save-badge {
  background: var(--accent);
  color: #fff;
  font-size: 0.6875rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.team-size-slider {
  max-width: 400px;
  margin: 0 auto 40px;
  text-align: center;
}

.team-size-slider label {
  display: block;
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: 12px;
}

.team-size-slider input[type="range"] {
  width: 100%;
  height: 6px;
  border-radius: 3px;
  background: var(--border);
  outline: none;
  -webkit-appearance: none;
}

.team-size-slider input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--primary);
  cursor: pointer;
  box-shadow: 0 2px 6px rgba(24,104,219,0.3);
}

.team-size-value {
  margin-top: 8px;
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 48px;
}

.pricing-card {
  background: var(--bg);
  border: 1.5px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: 28px;
  position: relative;
  transition: var(--transition);
}

.pricing-card:hover {
  box-shadow: var(--shadow);
  transform: translateY(-2px);
}

.pricing-card.popular {
  border-color: var(--primary);
  box-shadow: 0 0 0 1px var(--primary);
}

.popular-badge {
  position: absolute;
  top: -1px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: #fff;
  font-size: 0.6875rem;
  font-weight: 700;
  padding: 4px 14px;
  border-radius: 0 0 8px 8px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.pricing-card h3 {
  font-size: 1.25rem;
  margin-bottom: 4px;
}

.pricing-card .price {
  font-size: 2rem;
  font-weight: 800;
  margin: 12px 0;
}

.pricing-card .price span {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.pricing-card .description {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 20px;
  min-height: 40px;
}

.pricing-card ul {
  list-style: none;
  margin-bottom: 24px;
}

.pricing-card li {
  font-size: 0.875rem;
  padding: 5px 0;
  color: var(--text-secondary);
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.pricing-card li::before {
  content: '✓';
  color: var(--primary);
  font-weight: 700;
  flex-shrink: 0;
}

.pricing-card .btn {
  width: 100%;
}

.comparison-section {
  padding: 40px 0 80px;
}

.comparison-table-wrap {
  overflow-x: auto;
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9375rem;
}

.comparison-table th,
.comparison-table td {
  padding: 14px 16px;
  text-align: left;
  border-bottom: 1px solid var(--border-light);
}

.comparison-table th {
  font-weight: 600;
  background: var(--bg-warm);
  position: sticky;
  top: 0;
}

.comparison-table th:first-child {
  border-radius: var(--radius-sm) 0 0 0;
}

.comparison-table th:last-child {
  border-radius: 0 var(--radius-sm) 0 0;
}

.comparison-table td:first-child {
  font-weight: 500;
}

.comparison-table .check {
  color: var(--primary);
  font-weight: 700;
}

.comparison-table .dash {
  color: var(--text-muted);
}

/* ============================================
   FAQ
   ============================================ */

.faq-section {
  padding: 60px 0 80px;
  background: var(--bg-warm);
}

.faq-item {
  background: var(--bg);
  border-radius: var(--radius);
  margin-bottom: 12px;
  overflow: hidden;
  border: 1px solid var(--border-light);
}

.faq-question {
  width: 100%;
  padding: 20px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: none;
  border: none;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  text-align: left;
  color: var(--text);
}

.faq-question .icon {
  font-size: 1.25rem;
  color: var(--text-muted);
  transition: var(--transition);
  flex-shrink: 0;
  margin-left: 12px;
}

.faq-item.open .faq-question .icon {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-item.open .faq-answer {
  max-height: 400px;
  padding: 0 24px 20px;
}

.faq-answer p {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  line-height: 1.7;
}

/* ============================================
   AI Features
   ============================================ */

.ai-features {
  padding: 60px 0;
}

.ai-features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
}

.ai-feature-card {
  background: var(--bg-warm);
  border-radius: var(--radius);
  padding: 28px;
  transition: var(--transition);
}

.ai-feature-card:hover {
  box-shadow: var(--shadow);
}

.ai-feature-card .badge {
  display: inline-block;
  background: var(--accent);
  color: #fff;
  font-size: 0.625rem;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 4px;
  text-transform: uppercase;
  margin-bottom: 10px;
}

.ai-feature-card h4 {
  font-size: 1.0625rem;
  margin-bottom: 6px;
}

.ai-feature-card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* ============================================
   Enterprise Page
   ============================================ */

.enterprise-hero {
  padding: 80px 0;
  background: linear-gradient(135deg, #f0f5ff, #faf0ff);
}

.enterprise-hero .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.enterprise-hero h1 {
  margin-bottom: 16px;
}

.enterprise-hero p {
  font-size: 1.125rem;
  color: var(--text-secondary);
  margin-bottom: 28px;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin: 48px 0;
}

.stat-item {
  text-align: center;
}

.stat-number {
  font-size: 3rem;
  font-weight: 800;
  color: var(--primary);
  line-height: 1;
  margin-bottom: 8px;
}

.stat-label {
  font-size: 0.9375rem;
  color: var(--text-secondary);
}

.benefit-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

